                    now = time.monotonic()
                    cooldown = (
                        self.preferences.whatsapp_cooldown_seconds
                        if self.preferences
                        else self.settings.whatsapp_cooldown_seconds
                    )
                    ready = [
                        person
                        for person in contacts
