        except (ProviderError, TimeoutError) as exc:
            uncertain = isinstance(exc, TimeoutError) or exc.code in {
                "transport_error",
                "acceptance_unconfirmed",
                "response_too_large",
            }
            code = exc.code if isinstance(exc, ProviderError) else "transport_error"
            reason = {
